/**
 * AnswerPanel – Displays the generated LLM answer.
 *
 * Props:
 *   answer – The text generated by the model.
 *   model  – Identifier of the model that produced the output.
 */

import React from "react";

export default function AnswerPanel({ answer, model }) {
  return (
    <div className="panel answer-panel">
      <h2>Answer</h2>
      <p className="answer-text">{answer}</p>
      <span className="model-badge">{model}</span>
    </div>
  );
}
